Tool response:
Tool: record_deal_financing
Description: Record financing details for a specific deal
Parameters:
    {
      "type": "object",
      "properties": {
        "deal_id": {
          "type": "integer",
          "description": "Unique identifier for the deal",
          "title": "Deal Id"
        },
        "loan_amount": {
          "type": "number",
          "title": "Loan Amount",
          "description": "Total loan amount requested"
        },
        "term_months": {
          "type": "integer",
          "title": "Term Months",
          "description": "Loan term in months"
        },
        "apr": {
          "type": "number",
          "title": "Apr",
          "description": "Annual Percentage Rate"
        },
        "monthly_payment": {
          "type": "number",
          "title": "Monthly Payment",
          "description": "Monthly payment amount"
        },
        "lender": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Lender",
          "description": "Name of the lending institution"
        },
        "financing_type": {
          "anyOf": [
            {
              "type": "string",
              "enum": [
                "loan",
                "lease",
                "cash"
              ]
            },
            {
              "type": "null"
            }
          ],
          "title": "Financing Type",
          "description": "Type of financing used"
        },
        "start_date": {
          "anyOf": [
            {
              "type": "string",
              "format": "date"
            },
            {
              "type": "null"
            }
          ],
          "title": "Start Date",
          "description": "Start date of the financing"
        }
      },
      "required": [
        "deal_id",
        "loan_amount",
        "term_months",
        "apr",
        "monthly_payment"
      ]
    }

